import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import { Switch } from "@/registry/erbium/ui/switch";

export default function SwitchReadOnly() {
  return (
    <Field orientation="horizontal">
      <Switch readOnly defaultChecked />
      <FieldLabel>Managed by your organization</FieldLabel>
    </Field>
  );
}

import ExampleSwitchReadOnly from "../examples/switch-read-only";

const Example = () => <ExampleSwitchReadOnly />;

export default Example;
